llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Pethidine, a close N-methylpiperidine ester analogue, has absolute oral bioavailability of 0.57 ± 0.13 in normal subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Solifenacin, an antimuscarinic with the same therapeutic class as propiverine, has absolute oral bioavailability of 88% (95% CI 75.8–102.1) in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ketanserin, a piperidine-containing drug, has absolute oral bioavailability of 55.5 ± 8.7% in healthy male subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, despite first-pass metabolism, has absolute oral bioavailability of 32 ± 7% in normal subjects, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Netupitant has high absolute oral bioavailability of 63–87% in humans, supporting high F for a lipophilic amine-containing scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values well above 20% (approximately 32–88%), including structurally and pharmacologically related N-methylpiperidine esters and antimuscarinics; therefore propiverine is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for propiverine itself is included in the evidence set.",
    "Some analogues show wide interindividual variability, but their central estimates remain above the 20% threshold.",
    "No high-transfer low-bioavailability analogue was retrieved to contradict the supportive pattern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

